function distinctPortraits(rows){const seen=new Set();return rows.filter(p=>{const image=portraitUrl(p);if(seen.has(image))return false;seen.add(image);return true;});}
function gangRules(){return typeof RULES_DATA==='object'?RULES_DATA.gangTypes||[]:[];}
function slotFor(g){if(g.customGangTypeId||g.custom_gang_type_id||g.isCustomGangType)return null;const type=gangRules().find(t=>t.id===(g.gangTypeId||g.gang_type_id)||t.name===g.faction||t.gang_type===g.faction),parent=type?.parent_gang_type_id&&gangRules().find(t=>t.id===type.parent_gang_type_id),name=g.faction||g.gang_type||type?.name||type?.gang_type||'';if(type?.parent_gang_type_id&&!parent)return null;const parentName=parent?.name||parent?.gang_type;return {group:groupAliases[parentName||name]||parentName||name,label:parent?name:null};}
